from PIL import Image,ImageDraw
import numpy as np
from scipy.ndimage import distance_transform_edt

def dense(points,per=30):
 p=np.asarray(points,float); e=np.vstack([p[0],p,p[-1]]); out=[]
 for i in range(1,len(e)-2):
  p0,p1,p2,p3=e[i-1:i+3]
  for t in np.linspace(0,1,per,endpoint=False):
   out.append(.5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t**3))
 out.append(p[-1]); return np.array(out)

p=[(337,515),(336,500),(331,478),(326,456),(324,434),(327,413),(320,392),(302,368),(314,383),(330,389),(348,382),(368,372),(383,393),(403,399),(424,390),(446,379),(468,365),(489,350),(510,336),(508,315),(501,294),(490,273),(475,257),(455,249),(432,248)]
im0=Image.open('/app/target.png').convert('RGB'); mask=np.array(im0)[:,:,0]<100; D=distance_transform_edt(mask)
s=dense(p); out=[];ds=[]
for x,y in s:
 ix=int(round(np.clip(x,0,1023)));iy=int(round(np.clip(y,0,1023))); ds.append(D[iy,ix]);
 if not mask[iy,ix]:out.append((ix,iy))
print('samples',len(s),'outside',len(out),out[:20], 'dist px',np.percentile(ds,[0,10,25,50,75,90,100]))
d=ImageDraw.Draw(im0)
old=[(506,313),(504,306),(500,294),(493,279),(482,264),(463,253),(446,249),(432,248)]
for pts,col in [(old,(255,0,0)),(p,(0,200,0))]:
 q=dense(pts)
 for a,b in zip(q[:-1],q[1:]):d.line([tuple(a),tuple(b)],fill=col,width=4)
im0.crop((280,220,740,820)).resize((690,900)).save('/app/output/correction_preview.png')
